import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"晚餐邀请邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/05-dinner-invitation.md","filePath":"zh/more/maltese/practice/emails/05-dinner-invitation.md"}'),e={name:"zh/more/maltese/practice/emails/05-dinner-invitation.md"},o=r('<h1 id="晚餐邀请邮件" tabindex="-1">晚餐邀请邮件 <a class="header-anchor" href="#晚餐邀请邮件" aria-label="Permalink to &quot;晚餐邀请邮件&quot;">​</a></h1><p><strong>场景：</strong> Anna 邀请朋友 Mark 到家里吃晚餐。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Mingħand（发件人 From）：</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data（日期）：</strong> 12 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Stedina għall-ikla ta&#39; filgħaxija</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data:</strong> 12 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Stedina għall-ikla ta&#39; filgħaxija</p><p>Għażiż Mark,</p><p>Nispera li inti tajjeb.</p><p>Nixtieq nistednek għall-ikla ta&#39; filgħaxija d-dar tiegħi nhar il-Ġimgħa.</p><p>Se nibdew fis-sebgħa ta&#39; filgħaxija.</p><p>Se nkunu ftit ħbieb u nieklu flimkien.</p><p>Se nipprepara platt Malti u deżerta.</p><p>Jekk jogħġbok, għidli jekk għandek xi preferenzi għall-ikel.</p><p>Nispera li tkun tista&#39; tiġi.</p><p>Tislijiet, Anna</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></p><p><strong>整句：</strong> 收件人（To）：mark.b@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></td><td>邮箱地址</td><td>收件人（Mark）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>整句：</strong> 发件人（From）：anna.c@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>邮箱地址</td><td>发件人（Anna）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 12 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 12 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>12</td><td>十二</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Stedina għall-ikla ta&#39; filgħaxija</p><p><strong>整句：</strong> 主题：晚餐邀请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Stedina</td><td>邀请</td><td>阴性名词</td></tr><tr><td>għall-ikla</td><td>参加晚餐</td><td><code>għal</code> + <code>l-ikla</code> 的缩合形式</td></tr><tr><td>ta&#39;</td><td>……的；在……时段</td><td>连接名词和时间表达</td></tr><tr><td>filgħaxija</td><td>在晚上</td><td>时间表达</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Mark,</p><p><strong>整句：</strong> 亲爱的马克：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiż</td><td>亲爱的</td><td>阳性单数称呼形式</td></tr><tr><td>Mark</td><td>马克</td><td>人名</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li inti tajjeb.</p><p><strong>整句：</strong> 希望你一切都好。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数形式</td></tr><tr><td>li</td><td>……；引导从句</td><td>连词</td></tr><tr><td>inti</td><td>你</td><td>第二人称单数代词</td></tr><tr><td>tajjeb</td><td>好的</td><td>阳性形式；女性形式为 <code>tajba</code></td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq nistednek għall-ikla ta&#39; filgħaxija d-dar tiegħi nhar il-Ġimgħa.</p><p><strong>整句：</strong> 我想邀请你星期五晚上到我家吃晚餐。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nixtieq</td><td>我想；我希望</td><td>礼貌表达愿望</td></tr><tr><td>nistednek</td><td>我邀请你</td><td>邀请动词的第一人称形式，含第二人称单数宾语后缀</td></tr><tr><td>għall-ikla</td><td>去吃饭；参加晚餐</td><td><code>għal</code> + 定冠词 <code>l-</code> 与 <code>ikla</code> 缩合</td></tr><tr><td>ta&#39;</td><td>……的；在……时段</td><td>连接名词和时间表达</td></tr><tr><td>filgħaxija</td><td>在晚上</td><td>时间表达</td></tr><tr><td>d-dar</td><td>在家；家里</td><td><code>id-dar</code> 的常见缩合写法</td></tr><tr><td>tiegħi</td><td>我的</td><td>第一人称单数所有格</td></tr><tr><td>nhar</td><td>在……那天</td><td>引出星期或日期</td></tr><tr><td>il-Ġimgħa</td><td>星期五</td><td>星期名称通常带定冠词</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Se nibdew fis-sebgħa ta&#39; filgħaxija.</p><p><strong>整句：</strong> 我们将在晚上七点开始。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>将来标记</td></tr><tr><td>nibdew</td><td>我们开始</td><td>第一人称复数形式</td></tr><tr><td>fis-sebgħa</td><td>在七点</td><td><code>f&#39;</code> 与钟点定冠词形式缩合</td></tr><tr><td>ta&#39;</td><td>……的；在……时段</td><td>连接钟点与时段</td></tr><tr><td>filgħaxija</td><td>在晚上</td><td>时间表达</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Se nkunu ftit ħbieb u nieklu flimkien.</p><p><strong>整句：</strong> 会有几个朋友，我们一起吃饭。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>将来标记</td></tr><tr><td>nkunu</td><td>我们将会是；我们会在</td><td><code>ikun</code> 的第一人称复数形式</td></tr><tr><td>ftit</td><td>几个；少量</td><td>数量词</td></tr><tr><td>ħbieb</td><td>朋友们</td><td><code>ħabib</code> 的复数</td></tr><tr><td>u</td><td>和；并且</td><td>连词</td></tr><tr><td>nieklu</td><td>我们吃</td><td>第一人称复数形式</td></tr><tr><td>flimkien</td><td>一起</td><td>副词</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Se nipprepara platt Malti u deżerta.</p><p><strong>整句：</strong> 我会准备一道马耳他菜和甜点。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>将来标记</td></tr><tr><td>nipprepara</td><td>我准备</td><td>第一人称单数形式</td></tr><tr><td>platt</td><td>一道菜；盘子</td><td>阳性名词；此处指一道菜</td></tr><tr><td>Malti</td><td>马耳他式的</td><td>阳性单数形式，与 <code>platt</code> 一致</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>deżerta</td><td>甜点</td><td>阴性名词</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Jekk jogħġbok, għidli jekk għandek xi preferenzi għall-ikel.</p><p><strong>整句：</strong> 麻烦告诉我，你对食物有什么偏好吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jekk jogħġbok</td><td>请；麻烦你</td><td>固定礼貌表达</td></tr><tr><td>għidli</td><td>告诉我</td><td><code>għid</code>“告诉” + <code>-li</code>“我”</td></tr><tr><td>jekk</td><td>是否；如果</td><td>此处引出间接疑问</td></tr><tr><td>għandek</td><td>你有</td><td><code>għand</code> 的第二人称单数形式</td></tr><tr><td>xi</td><td>一些；任何</td><td>不定限定词</td></tr><tr><td>preferenzi</td><td>偏好</td><td><code>preferenza</code> 的复数</td></tr><tr><td>għall-ikel</td><td>对食物；关于吃的</td><td><code>għal</code> + 定冠词 <code>l-</code> 与 <code>ikel</code> 缩合</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li tkun tista&#39; tiġi.</p><p><strong>整句：</strong> 希望你能来。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数形式</td></tr><tr><td>li</td><td>……；引导从句</td><td>连词</td></tr><tr><td>tkun</td><td>你会是；你能够</td><td><code>ikun</code> 的第二人称/从属形式</td></tr><tr><td>tista&#39;</td><td>你可以</td><td>第二人称单数形式</td></tr><tr><td>tiġi</td><td>你来</td><td>第二人称单数形式</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, Anna</p><p><strong>整句：</strong> 此致敬意，安娜（邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Anna</td><td>安娜</td><td>人名</td></tr></tbody></table>',53),i=[o];function n(l,h,g,s,b,c){return d(),a("div",null,i)}const k=t(e,[["render",n]]);export{m as __pageData,k as default};
